package com.smartblog.util;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.Date;
@Component public class JwtUtil { @Value("${jwt.secret}") private String secret; @Value("${jwt.access-expiration}") private Long accessExpiration; private SecretKey getKey(){return Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));} public String generateAccessToken(Long userId,String username,String sessionId,String jti){Date now=new Date(); Date exp=new Date(now.getTime()+accessExpiration); return Jwts.builder().setSubject(String.valueOf(userId)).setId(jti).claim("username",username).claim("sessionId",sessionId).claim("tokenType","ACCESS").setIssuedAt(now).setExpiration(exp).signWith(getKey(),SignatureAlgorithm.HS256).compact();} public Claims parseToken(String token){return Jwts.parserBuilder().setSigningKey(getKey()).build().parseClaimsJws(token).getBody();} public boolean validateToken(String token){try{return "ACCESS".equals(parseToken(token).get("tokenType",String.class));}catch(JwtException|IllegalArgumentException e){return false;}} public Long getUserId(String token){return Long.valueOf(parseToken(token).getSubject());} public String getUsername(String token){return parseToken(token).get("username",String.class);} public String getSessionId(String token){return parseToken(token).get("sessionId",String.class);} public String getJti(String token){return parseToken(token).getId();} public Long getAccessExpirationSeconds(){return accessExpiration/1000;} }
